function handleInstantCheckout(e) {
			if (e) e.preventDefault();

			var triggerBtn = e ? e.currentTarget : stickyBuyBtn;
			if (triggerBtn && triggerBtn.classList.contains('is-loading')) return;

			if (!validateVariations()) return;

			// Visual button feedback & anti-duplicate lock
			var originalHtml = '';
			if (triggerBtn) {
				triggerBtn.classList.add('is-loading');
				originalHtml = triggerBtn.innerHTML;
				triggerBtn.innerHTML = '<span class="tt4m-spinner"></span> Đang chuyển...';
			}

			// Atomic Server-Side Redirect: Inject tt4m_buy_now hidden field into cart form
			var cartForm = document.querySelector('form.cart');
			var flag = null;
			if (cartForm) {
				flag = cartForm.querySelector('input[name="tt4m_buy_now"]');
				if (!flag) {
					flag = document.createElement('input');
					flag.type = 'hidden';
					flag.name = 'tt4m_buy_now';
					flag.value = '1';
					cartForm.appendChild(flag);
				} else {
					flag.value = '1';
				}
			}

			var redirected = false;
			function goToCheckout() {
				if (redirected) return;
				redirected = true;
				window.location.href = TT4M.checkoutUrl;
			}

			// Reset handler on request failure, abort, or error
			function resetPurchaseState(errorMessage) {
				if (redirected) return;

				if (triggerBtn) {
					triggerBtn.classList.remove('is-loading');
					triggerBtn.innerHTML = originalHtml || '<span>Mua ngay</span>';
				}
				if (mainAtc) {
					mainAtc.classList.remove('is-loading', 'loading');
				}
				if (stickyBuyBtn && stickyBuyBtn !== triggerBtn) {
					stickyBuyBtn.classList.remove('is-loading');
				}
				if (flag) {
					flag.value = '0';
				}

				if (window.jQuery) {
					window.jQuery(document.body).off('added_to_cart.tt4m_buy');
					window.jQuery(document).off('ajaxError.tt4m_buy');
				}
